import {Chess} from './vendor/chess.js';
export function briefComment(move,before,after,grade,tone='warm'){
 const c=new Chess(move.after);if(c.isCheckmate())return 'Scacco matto: hai chiuso la partita! Il re avversario non ha più risposte legali.';
 if(c.isStalemate())return 'Attenzione: è stallo. Il re non è sotto scacco, ma non ci sono mosse legali: la partita è patta.';
 if(!grade)return 'Mossa registrata. Non ho ancora una valutazione affidabile: continua a controllare la sicurezza dei tuoi pezzi.';
 const negative=grade.loss>.05;let fact='';
 if(negative){if(after?.mate!=null&&after.cp*(move.color==='w'?1:-1)<0)fact='Il motore vede un attacco di matto contro il tuo re: prima di muovere, controlla la sua sicurezza.';else if(c.moves({verbose:true}).some(m=>m.captured&&m.to===move.to))fact=`Il pezzo in ${move.to} può essere catturato. Controlla se hai contato bene anche le ricatture.`;else fact='Il motore preferisce altre scelte. Prima di impegnarti in un piano, controlla cosa hai lasciato all’avversario.';return (tone==='direct'?'Da rivedere. ':tone==='quiet'?'Attenzione. ':'Qui possiamo fare meglio. ')+fact}
 if(move.flags.includes('k')||move.flags.includes('q'))fact='Hai arroccato e attivato la torre.';else if(move.captured)fact='Questa cattura mantiene bene la posizione secondo il motore.';else if(['n','b'].includes(move.piece)&&move.from[1]===(move.color==='w'?'1':'8'))fact='Hai portato un pezzo fuori dalla traversa iniziale.';else if(['d4','e4','d5','e5'].includes(move.to))fact='Hai occupato una casa centrale senza peggiorare sensibilmente la posizione.';else if(c.isCheck())fact='Hai dato scacco mantenendo una buona valutazione.';else fact='La posizione regge bene. Continua a sviluppare il tuo piano.';
 return (tone==='direct'?'Buona scelta. ':tone==='quiet'?'Bene. ':'Ben giocato! ')+fact;
}
export function strategicHint(c){if(c.isCheck())return 'Il tuo re è sotto scacco: prima risolvi questo problema.';const side=c.turn(),enemy=side==='w'?'b':'w';const attacked=c.board().flat().filter(p=>p&&p.color===side&&p.type!=='k'&&c.isAttacked(p.square,enemy));if(attacked.length)return 'Prima di scegliere un piano, controlla i tuoi pezzi attaccati e i loro difensori.';return c.moveNumber()<12?'Chiediti quale pezzo deve ancora entrare in gioco e come rendere più sicuro il re.':'Confronta il tuo pezzo meno attivo con le debolezze dell’avversario. Quale miglioramento puoi preparare?'}
